/* Месяцеслов «Православных» — 11.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M11: SaintRec[] = [
  { key: "11-01", name: "Прор. Иоиля", kind: "saint", desc: "Происходил из колена Рувимова. Предсказал запустение Иерусалима и прекращение ветхозаветных жертвоприношений. Он же пророчествовал, что придет время, когда на всякую плоть будет изливаться Святой Дух по вере в Иисуса Христа, Спасителя мира." },
  { key: "11-01", name: "мч. Уара Египетского и с ним семи учителей христианских", kind: "saint", desc: "Св. мученик Уар, римский военачальник в Египте, тайно исповедовал христианство. Он помогал заключенным единоверцам, принося им пищу и утешение. Однажды, после ночной беседы с семью христианскими учителями, осужденными на казнь, Уар вышел вместе с ними на место казни." },
  { key: "11-01", name: "Перенесение мощей прп. Иоанна Рыльского", kind: "saint", desc: "Прп. Иоанн Рыльский, великий болгарский святой, родился около 876 года в селе Скрино. Рано осиротев, стал пастухом, после раздал имущество и ушел в пустыню." },
  { key: "11-01", name: "сщмч. Садока, епископа Персидского, и с ним 128-ми мучеников", kind: "saint", desc: "Сщмч. Садок, епископ Персидский, жил в первой половине IV века. За проповедь христианства он был арестован по приказу царя Сапора II вместе с 128 верующими." },
  { key: "11-01", name: "Александра Никольского", kind: "saint", desc: "Сщмч. Александр Никольский (1883–1937) служил священником в селе Паново-Осаново Горьковской области. Был арестован в сентябре 1937 года вместе с группой духовенства за проведение торжественной службы в праздничный день, что власти расценили как отрыв крестьян от колхозных работ." },
  { key: "11-01", name: "Сергия Покровского", kind: "saint", desc: "Сщмч. Сергий Покровский (1880–1937) окончил Калужскую духовную семинарию. В юности увлекался революционными идеями, но после рукоположения в священники в 1907 году полностью посвятил себя служению Церкви." },
  { key: "11-02", name: "Вмч. Артемия Антиохийского", kind: "saint", desc: "Св. вмч. Артемий, военачальник при императорах св. Константине Великом и Констанции, был назначен наместником Египта. С приходом к власти Юлиана Отступника, яростного гонителя христиан, Артемий публично обличил императора в нечестии." },
  { key: "11-02", name: "Прав. отрока Артемия Веркольского", kind: "saint", desc: "Св. Артемий Веркольский (XVI в.) ‒ отрок-праведник, живший в селе Верколе. В 12 лет погиб от удара молнии, после чего односельчане, считая такую смерть знаком гнева Божия, оставили его тело непогребённым в лесу." },
  { key: "11-02", name: "прп. Гавриила Самтаврийского, архимандрита (1995)", kind: "saint", desc: "Прп. Гавриил (Ургебадзе) родился в 1929 году в Тбилиси. Принял монашество в 26 лет. В 1965 году публично сжёг портрет Ленина, за что был помещён в психиатрическую больницу." },
  { key: "11-02", name: "Сщмч. Николая Любомудрова, пресвитера", kind: "saint", desc: "Сщмч. Николай Любомудров (1862–1918) был священником села Лацкое Ярославской губернии. Он 32 года самоотверженно служил приходу: основал библиотеку, проводил народные чтения, боролся с пьянством." },
  { key: "11-02", name: "Зосимы Пепенина", kind: "saint", desc: "Сщмч. Зосима Пепенин родился в 1888 году. Окончил Иркутскую духовную семинарию, в 1913 году рукоположен в священника. Служил в различных приходах Сибири и центральной России, последним местом служения стал храм в подмосковном Крылатском." },
  { key: "11-02", name: "Иоанна Ганчева", kind: "saint", desc: "Сщмч. Иоанн Ганчев (1878–1937) родился во Владимирской губернии, окончил Петроградскую духовную семинарию. В 1910 году был рукоположен в священника и направлен на служение в Азербайджан, где стал настоятелем собора Рождества Богородицы в Баку." },
  { key: "11-02", name: "Иоанна Речкина", kind: "saint", desc: "Сщмч. Иоанн Речкин (1872–1937) родился в Тульской губернии. Окончил Московскую духовную академию. Служил священником в селе Высокое Харьковской области." },
  { key: "11-02", name: "Иоанна Родионова", kind: "saint", desc: "Сщмч. Иоанн Родионов (1881–1937) родился в Курской губернии. Получил высшее историческое образование. Служил священником в городе Ессентуки на Северном Кавказе." },
  { key: "11-02", name: "Николая Фигурова", kind: "saint", desc: "Сщмч. Николай Фигуров (1886–1937) родился в Нижегородской губернии и служил священником в родном селе. В 1928 году был арестован и выслан в Бузулук. В 1935 году осужден за антисоветскую пропаганду и приговорен к трём годам исправительно-трудовых лагерей." },
  { key: "11-02", name: "Леонида Никольского", kind: "saint", desc: "Сщмч. Леонид Никольский (1876–1937) служил в различных селах Вятской губернии. В 1931 году был арестован за антисоветскую агитацию и приговорен к пяти годам лагерей." },
  { key: "11-02", name: "Иоанна Талызина", kind: "saint", desc: "Сщмч. Иоанн Талызин (1888–1937) окончил духовное училище и был рукоположен в священника к храму села Ордино Угличского уезда. В 1930 году был арестован и осужден на три года ссылки." },
  { key: "11-02", name: "Александра Орлова", kind: "saint", desc: "Сщмч. Александр Орлов (1875–1937) окончил Тамбовскую духовную семинарию, в 1903 году рукоположен во священника. Неоднократно подвергался арестам за веру." },
  { key: "11-02", name: "Михаила Исаева", kind: "saint", desc: "Сщмч. Михаил Исаев (1875–1937) служил диаконом в селе Студенки Липецкой области. В 1935 году был арестован за участие в «контрреволюционной группе», возглавляемой епископом Уаром (Шмариным) и осужден на пять лет лагерей." },
  { key: "11-02", name: "Петра Кравца, диаконов", kind: "saint", desc: "Сщмч. Петр Кравец (1885–1937), диакон, служил в Саратове и Казани. Неоднократно арестовывался за борьбу с обновленчеством и антисоветскую агитацию. В 1935 году осужден на три года Карлага." },
  { key: "11-03", name: "Прп. Илариона Великого", kind: "saint", desc: "Прп. Иларион Великий (291–371/372) родился в Палестине. Получив образование в Александрии, он принял крещение и стал учеником прп. Антония Великого. После смерти родителей раздал имущество и удалился в пустыню близ Маиума, где провел годы в строгом аскетическом подвиге, борясь с бесовскими искушениями." },
  { key: "11-03", name: "Перенесение мощей свт. Илариона, епископа Меглинского", kind: "saint", desc: "Свт. Иларион Меглинский, знатный константинополец, в 18 лет принял монашество, прославившись кротостью, милосердием и молитвенным подвигом. Около 1134 года он был поставлен епископом Меглинским и ревностно боролся с ересями, утверждая православную веру." },
  { key: "11-03", name: "Прп. Илариона, схимника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Иларион Печерский, схимник, был учеником и сподвижником прп. Феодосия Печерского в XI веке. Он известен как строгий аскет, проводивший дни и ночи в молитве и посте." },
  { key: "11-03", name: "прп. Илариона Псковоезерского, Гдовского", kind: "saint", desc: "Прп. Иларион Псковоезерский, Гдовский, был учеником прп. Евфросина Псковского. В XV веке он избрал для подвижнической жизни уединенное место на берегу реки Желчи близ Чудского озера, где основал Озерский Покровский монастырь (1460 г.)." },
  { key: "11-03", name: "Павлина (Крошечкина), архиепископа Могилевского", kind: "saint", desc: "Сщмч. Павлин (Крошечкин) родился в 1879 году. Приняв монашество, окончил Московскую духовную академию. В 1921 году хиротонисан во епископа и служил на различных кафедрах, активно противостоя обновленчеству." },
  { key: "11-03", name: "Аркадия (Ершова), епископа Екатеринбургского, и", kind: "saint", desc: "Сщмч. Аркадий (Ершов) родился в 1878 году. Окончив Пермскую духовную семинарию, служил полковым священником в Первую мировую войну. В 1924 году по благословению Патриарха Тихона был хиротонисан во епископа Кунгурского и возглавил борьбу с обновленческим расколом на Урале." },
  { key: "11-03", name: "Анатолия Левицкого", kind: "saint", desc: "Сщмч. Анатолий Левицкий (1894–1937) окончил Вятскую духовную семинарию и был рукоположен в священника. В 1933 году арестован и приговорен к пяти годам исправительно-трудовых лагерей." },
  { key: "11-03", name: "Никандра Чернелевского", kind: "saint", desc: "Сщмч. Никандр Чернелевский (1880–1937) родился в Черниговской губернии. Окончил Холмскую духовную семинарию, в 1902 году рукоположен во священника. В 1936 году арестован в Харькове за контрреволюционную агитацию и осужден на четыре года лагерей." },
  { key: "11-03", name: "мч. Киприана Анникова", kind: "saint", desc: "Мч. Киприан Анников (1875–1937) родился в Тамбовской губернии. Занимался хлебопашеством и сапожным ремеслом. В 1929 году его семья была раскулачена и выслана в Казахстан." },
  { key: "11-03", name: "сщмч. Дамиана (Воскресенского), архиепископа Курского", kind: "saint", desc: "Сщмч. Дамиан (Воскресенский), архиепископ Курский, родился в 1873 году в семье священника. Окончив Санкт-Петербургскую духовную академию, он принял монашество в 1904 году, а в 1918 году был хиротонисан во епископа." },
  { key: "11-03", name: "Константина Чекалова", kind: "saint", desc: "Сщмч. Константин Чекалов (1889–1937) служил в храмах Тверской епархии, совмещая пастырское служение с преподаванием Закона Божия. В 1932 году был осужден на три года лагерей." },
  { key: "11-03", name: "Сергия Смирнова", kind: "saint", desc: "Сщмч. Сергий Смирнов (1893–1937) окончил Ярославскую духовную семинарию и в 1919 году был рукоположен в священника. Служил в селе Санниково, проявив себя как ревностный пастырь и благотворитель." },
  { key: "11-03", name: "Василия Никольского", kind: "saint", desc: "Сщмч. Василий Никольский (1898–1937) родился в Тверской губернии. Окончил духовную семинарию и служил в сельских храмах епархии. В 1930 году был арестован за «контрреволюционную пропаганду» и сослан на три года." },
  { key: "11-03", name: "Феодора Беляева", kind: "saint", desc: "Сщмч. Феодор Беляев (1867–1937) родился в Новгородской губернии. Окончил Олонецкую духовную семинарию. Служил в Троицком храме села Улома. В 1922 году активно противостоял изъятию церковных ценностей, за что был арестован и осужден на четыре года лагерей." },
  { key: "11-04", name: "Празднование Казанской иконе Божией Матери", kind: "icon", desc: "Празднование Казанской иконе Божией Матери (в память избавления Москвы и России от поляков в 1612 г. 8 июля* 1579 года, через четверть века после покорения Иоанном Грозным Казани — столицы царства Татарского (в 1552 году) и последовавшего в" },
  { key: "11-04", name: "равноап. Аверкия, епископа Иерапольского, чудотворца", kind: "saint", desc: "Св. равноапостольный Аверкий, епископ Иерапольский, жил во II веке во Фригии. Прославился тем, что по велению Ангела сокрушил языческих идолов в своем городе." },
  { key: "11-04", name: "Серафима (Самойловича), архиепископа Угличского, и с ним", kind: "saint", desc: "Сщмч. Серафим (Самойлович, 1881-1937), архиепископ Угличский, был видным миссионером и сподвижником будущего Патриарха Тихона. В 1920 году хиротонисан во епископа." },
  { key: "11-04", name: "Владимира Соболева", kind: "saint", desc: "Сщмч. Владимир Соболев (1874-1937) был арестован в 1935 году по обвинению в «контрреволюционной агитации» и приговорен к 10 годам исправительно-трудовых лагерей." },
  { key: "11-04", name: "Александра Андреева", kind: "saint", desc: "Сщмч. Александр Андреев родился в 1901 году в Москве. Служил в московских храмах, был настоятелем Софийской церкви на Софийской набережной. В 1929 году арестован за организацию сестричества и «антисоветскую агитацию» и сослан в Казахстан на три года." },
  { key: "11-04", name: "Василия Богоявленского", kind: "saint", desc: "Сщмч. Василий Богоявленский (1879-1937), пресвитер, служил в Новгородской епархии. В 1934 году арестован по обвинению в «контрреволюционной деятельности» и приговорен к 5 годам исправительно-трудовых лагерей." },
  { key: "11-04", name: "Александра Лебедева", kind: "saint", desc: "Сщмч. Александр Лебедев родился в 1878 году. Служил священником в сёлах Воронежской области. В марте 1936 года был арестован и приговорён к пяти годам исправительно-трудовых лагерей." },
  { key: "11-04", name: "Германа", kind: "saint", desc: "Прмч. Герман (Полянский) родился в 1901 году. Принял монашество в 1926 году в московском Высоко-Петровском монастыре. Стал архимандритом и возглавил одну из тайных монашеских общин, активно занимаясь духовным окормлением молодежи." },
  { key: "11-04", name: "Мины (Шелаева), архимандритов", kind: "saint", desc: "Прмч. Мина (Шелаев) родился в 1882 году. Получив образование, стал учителем, а затем активным миссионером, занимаясь обращением старообрядцев в единоверие." },
  { key: "11-04", name: "Николая Богословского", kind: "saint", desc: "Сщмч. Николай Богословский родился в 1875 году. Окончив Казанскую духовную семинарию, был рукоположен в священника. В 1921 году окончил Казанскую духовную академию." },
  { key: "11-04", name: "Николая Ушакова", kind: "saint", desc: "Сщмч. Николай Ушаков родился в 1876 году в Ярославле. Окончил духовную семинарию и служил священником в селе Семеновском. В 1930 году был впервые арестован по обвинению в контрреволюционной деятельности и провел три месяца в тюрьме." },
  { key: "11-04", name: "прмч. Григория (Воробьева), игумена", kind: "saint", desc: "Прмч. Григорий (Воробьев) родился в 1883 году. Принял монашество в Александро-Свирском монастыре, был рукоположен в иеромонаха. Служил полковым священником, а затем фельдшером." },
  { key: "11-04", name: "Обретение мощей сщмч. Никодима (Кононова), епископа Белгородского", kind: "saint", desc: "Сщмч. Никодим (Кононов), епископ Белгородский, родился в 1871 году в семье священника. Окончил Санкт-Петербургскую Духовную академию, принял монашество." },
  { key: "11-04", name: "Андрониковская", kind: "saint", desc: "Андрониковская икона Божией Матери, известная также под именами Монемвасийской и Греческой, – родовая святыня греческого императора Андроника III Палеолога, по преданию, одна из написанных апостолом и евангелистом Лукой." },
  { key: "11-05", name: "Ап. от 70-ти Иакова, брата Господня по плоти", kind: "saint", desc: "Св. Иаков был сыном Иосифа Обручника от его первой жены и потому называется братом Господним. Он был первым епископом Иерусалимской церкви, председательствовал на Апостольском соборе в 51 году, и его слово было решающим." },
  { key: "11-05", name: "Перенесение мощей прав. Иакова Боровичского, Новгородского чудотворца", kind: "saint", desc: "Сведений о жизни не сохранилось. Прославился посмертно: в 1540-х годах его гроб на льдине трижды приплывал против течения к селу Боровичи (Новгородчина)." },
  { key: "11-05", name: "Свт. Игнатия, патриарха Константинопольского", kind: "saint", desc: "Свт. Игнатий, патриарх Константинопольский, происходил из императорского рода и в юности был насильно пострижен в монахи. Жизнь в монастыре укрепила его в вере и благочестии." },
  { key: "11-05", name: "прп. Елисея Лавришевского", kind: "saint", desc: "Прп. Елисей Лавришевский, сын князя Тройната, был знатным вельможей при дворе литовского князя Миндовга. Приняв христианство, он оставил мирскую жизнь и около 1225 года основал Лавришевский монастырь под Новогрудком." },
  { key: "11-05", name: "Николая Агафоникова", kind: "saint", desc: "Сщмч. Николай Агафоников родился в 1876 году. Окончил Вятскую духовную семинарию, в 1899 году был рукоположен в священника и 17 лет служил в селе Загорье." },
  { key: "11-05", name: "Владимира Амбарцумова", kind: "saint", desc: "Сщмч. Владимир Амбарцумов родился в 1892 году в Саратове в лютеранской семье. Окончил Московский университет, участвовал в христианском студенческом движении, первоначально будучи баптистом." },
  { key: "11-05", name: "Александра Соловьева", kind: "saint", desc: "Сщмч. Александр Соловьев родился в 1893 году. С 1924 года служил в храме села Сляднево Московской области. В 1937 году, после временного закрытия, храм был вновь открыт его усилиями." },
  { key: "11-05", name: "Николая Архангельского", kind: "saint", desc: "Сщмч. Николай Архангельский родился в 1878 году. Окончил Московскую духовную семинарию, в 1915 году был рукоположен в священника. Служил в различных храмах Московской епархии." },
  { key: "11-05", name: "Емилиана Гончарова", kind: "saint", desc: "Сщмч. Емилиан Гончаров родился в 1882 году в крестьянской семье. Окончив учительскую семинарию, в 1921 году был рукоположен в священника. Служил в Саратовской епархии, а с 1932 года ‒ в храме села Рождествено Московской области." },
  { key: "11-05", name: "Созонта Решетилова", kind: "saint", desc: "Сщмч. Созонт Решетилов родился в 1894 году в крестьянской семье. После службы в армии был рукоположен в священника в 1921 году. Служил в храмах Киевской епархии, в 1928 году был осужден на три месяца за неуплату налогов." },
  { key: "11-05", name: "прмц. Антонии Тимофеевой, послушницы", kind: "saint", desc: "Прмц. Антония Тимофеева родилась в 1881/83 году в крестьянской семье. В 1903 году стала послушницей Московского Алексеевского монастыря. После его закрытия занималась пошивом одеял." },
  { key: "11-06", name: "Иконы Божией Матери «Всех скорбящих Радость»", year: "1688", kind: "icon", desc: "Сколько утешительного заключено в одном уже имени этой иконы — будящем, укрепляющем веру людей в Богоматерь, как в дивную Заступницу, которая спешит всюду, где слышится стон страдания людского, утирает слезы плачущих и в самом горе дает минуты отрады и радости небесной." },
  { key: "11-06", name: "Мч. Арефы и с ним 4299 мучеников", kind: "saint", desc: "Мч. Арефа, правитель христианского города Негран в Аравии, и с ним 4299 мучеников пострадали в VI веке от царя Дунаана, вознамерившегося истребить христианство в своей стране." },
  { key: "11-06", name: "прп. Зосимы (Верховского)", kind: "saint", desc: "Прп. Зосима (Верховский) родился в 1768 году в дворянской семье, с детства отличался благочестием и стремлением к подвижнической жизни. В 21 год, оставив военную службу, он удалился в пустынь, где стал учеником старца Василиска." },
  { key: "11-06", name: "и Феофила (XII–XIII), затворников Печерских, в Ближних пещерах", kind: "saint", desc: "Прп. Феофил затворник (XII–XIII вв.) в общей службе преподобным Антониевых пещер именуется как \"в чудесех изящный\". Погребён в Ближних пещерах Лавры. Преподобные Арефа, Сисой и Феофил, затворники Печерские (XII–XIII), подвизались в Киево-Пе" },
  { key: "11-06", name: "блж. Елезвоя, царя Ефиопского", kind: "saint", desc: "Блаженный Елезвой, царь Эфиопский, выступил против гонителя христиан иудея Дунаана, царя Аравийского, но потерпел поражение. Откровение от затворника указало, что причиной неудачи был его грех самовольной мести, ибо «Мне отмщение, Я воздам»." },
  { key: "11-06", name: "мц. Синклитикии Негранской и двух дщерей ее", kind: "saint", desc: "Св. мученица Синклитикия и её две дочери пострадали в VI веке от аравийского царя-иудея Дунаана, гонителя христиан. Будучи знатной вдовой, она воспитала дочерей в вере." },
  { key: "11-06", name: "свт. Афанасия, патриарха Цареградского", kind: "saint", desc: "Свт. Афанасий I, Патриарх Константинопольский, с юности посвятил себя монашеской жизни, подвизаясь на Афоне и в других обителях, где принял схиму. Дважды он занимал Константинопольскую кафедру (1289–1293 и 1303–1311), проявив себя как строг" },
  { key: "11-06", name: "прп. Георгия (Карслидиса), исп.", kind: "saint", desc: "Исповедник Георгий (Карслидис, 1901–1959) родился в Понте, рано осиротел и чудесным образом оказался в монастыре в Грузии, где принял постриг. Пережил тюрьму и чудесное спасение от расстрела (пуля отрикошетила от иконы Богородицы).", lifeId: "georgiy" },
  { key: "11-06", name: "прп. Арефы (Митренина), исп., иеромонаха", kind: "saint", desc: "Прписп. Арефа (Митренин) родился в 1879 году в Кронштадте. В 1902 году поступил в Валаамский монастырь, где принял монашество и был рукоположен в иеромонаха." },
  { key: "11-06", name: "Иоанна Смирнова", kind: "saint", desc: "Сщмч. Иоанн Смирнов родился в 1884 году в Ярославской губернии. Окончив духовное училище, он служил священником в селе Колегаево. Его проповеди, призывавшие к жизни по христианским заповедям, были расценены властями как контрреволюционная агитация." },
  { key: "11-06", name: "Николая Никольского", kind: "saint", desc: "Сщмч. Николай Никольский, родившийся в 1882 году, служил иереем в Ярославской епархии. В 1919 году ему инкриминировали участие в крестьянском восстании, и хотя два предыдущих ареста (1930, 1931) не привели к осуждению, в 1937 году он был арестован в третий раз." },
  { key: "11-06", name: "сщмч. Петра Богородского, пресвитера", kind: "saint", desc: "Сщмч. Петр Богородский (1878-1938) активно противостоял обновленческому расколу, за что был сослан на север и едва не умер от голода и тифа. После возвращения продолжил служение." },
  { key: "11-07", name: "Мартирия, диакона", kind: "saint", desc: "Прп. Мартирий Печерский, диакон, подвизавшийся в XIV веке в Киево-Печерской лавре, прославился строгой постнической жизнью, чистотой и даром чудотворений ещё при жизни." },
  { key: "11-07", name: "Мартирия затворника, Печерских, в Дальних пещерах", kind: "saint", desc: "О прп. Мартирии Печерском, затворнике, не сохранилось никаких сведений, кроме того, что он стяжал нетление и покоится в Феодосиевых пещерах в Киеве. В «Полном христианском месяцеслове» (Киев, 1875 г.) под 25-м числом октября сказано: «Преподобного Мартирия диакона и преподобного Мартирия, затворника Печерского»." },
  { key: "11-07", name: "мч. Анастасия Аквилейского", kind: "saint", desc: "Св. мученик Анастасий Аквилейский пострадал в III веке. За проповедь христианства в Далмации он был схвачен, мужественно исповедал веру во Христа и казнён язычниками, которые бросили его тело в море." },
  { key: "11-07", name: "прав. Тавифы Иоппийской", kind: "saint", desc: "Св. праведная Тавифа, жившая в I веке в Иоппии, принадлежала к христианской общине. После её смерти христиане призвали апостола Петра, находившегося неподалёку." },
  { key: "11-07", name: "Прп. Матроны (Власовой), исп., инокини", kind: "saint", desc: "Исповедница Матрона (Власова), инокиня, родившаяся в 1889 году в Нижегородской губернии, с детства воспитывалась в Серафимо-Дивеевском монастыре. После его закрытия в 1927 году вела тихую жизнь с сестрами, но трижды подвергалась арестам (19", lifeId: "matrona" },
  { key: "11-08", name: "Вмч. Димитрия Солунского", year: "ок. 306", kind: "feast", desc: "Родители, тайные христиане, крестили Димитрия и наставили в вере. Отец его, римский проконсул, умер, когда Димитрий достиг совершеннолетия. Император Максимиан Галерий, вступивший на престол в 305 году, назначил Димитрия на место отца властителем и воеводой Фессалонийской области.", lifeId: "dimitry-solunsky" },
  { key: "11-08", name: "Воспоминание землетрясения, бывшего в Царьграде", year: "740", kind: "feast", desc: "В 740 году Константинополь и многие города Византийской империи поразило страшное землетрясение. В столице рухнула часть башен Феодосиевой стены, разрушены были многие здания." },
  { key: "11-08", name: "Прп. Феофила Печерского, архиепископа Новгородского, в Дальних пещерах", kind: "saint", desc: "Прп. Феофил, архиепископ Новгородский, в XV веке возглавлял епархию в сложный период, когда часть новгородцев во главе с Марфой Борецкой склонялась к союзу с Литвой." },
  { key: "11-08", name: "мч. Луппа Солунского", kind: "saint", desc: "Мч. Лупп, верный слуга вмч. Димитрия Солунского, после казни господина взял его перстень и омочил одежду в его крови. Этими святынями он творил в Солуни многие чудеса." },
  { key: "11-08", name: "прп. Афанасия Мидикийского", kind: "saint", desc: "Прп. Афанасий Мидикийский, стремясь к иноческой жизни, тайно покинул дом, но был возвращён отцом. Впоследствии с родительского благословения он поступил в Мидикийский монастырь в Вифинии." },
  { key: "11-08", name: "прп. Димитрия Басарбовского, Болгарского", kind: "saint", desc: "Прп. Димитрий Басарбовский подвизался в пустыни в Болгарии близ города Рущука. Скончался в 1685 г. В 1779 г. мощи его были перенесены в Бухарест. Преподобный Димитрий родился в селе Басарбове (долина реки Русенски-Лом около города Русе)." },
  { key: "11-09", name: "Мч. Нестора Солунского", kind: "saint", desc: "Мученик Нестор, ученик св. Димитрия Солунского, во время гладиаторских игр вступил в бой с любимым силачом императора германцем Лием, который убивал многих христиан." },
  { key: "11-09", name: "Прп. Нестора Летописца, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Нестор Летописец, родившийся в Киеве в XI веке, в 17 лет стал иноком Киево-Печерского монастыря. Прославился высокой духовной жизнью. Он вошёл в историю как автор фундаментальных трудов: «Повести временных лет» ‒ первой летописи Древне" },
  { key: "11-09", name: "прп. Нестора, Некнижного, Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Нестор Некнижный был подвижником Киево-Печерского монастыря в Дальних пещерах. Он не был обучен грамоте, но стяжал духовную мудрость через чистоту сердца, пламенную молитву и слушание слова Божия." },
  { key: "11-09", name: "Обретение мощей блгв. кн. Андрея Смоленского в Переславле-Залесском", kind: "saint", desc: "Св. благоверный князь Андрей Смоленский, сын князя Феодора, тяготясь междоусобицами, тайно покинул свой удел и в смирении прибыл в Переяславль-Залесский." },
  { key: "11-09", name: "мч. Марка Фиваидского и иже с ним", kind: "saint", desc: "Мч. Марк Фиваидский пострадал за проповедь христианства в Азии. После жестоких истязаний он был казнён. За проповедь о Христе пострадал в Азии. После многих истязаний св. мученик Марк был умерщвлен." },
  { key: "11-09", name: "Прмч. Сергия (Чернухина), игумена", kind: "saint", desc: "Прмч. Сергий (Чернухин), родившийся в 1879 году, за исповедание веры дважды подвергался репрессиям: в 1931 году был сослан на три года, а в 1937 году арестован по ложному обвинению в \"контрреволюционной агитации\"." },
  { key: "11-10", name: "Вмц. Параскевы, нареченной Пятница", kind: "saint", desc: "Вмц. Параскева, названная в честь дня страданий Христовых (Пятница по-гречески Параскева), родилась в Иконии в III веке. Рано оставшись сиротой, она посвятила себя служению Богу, приняв обет девства и проповедуя среди язычников." },
  { key: "11-10", name: "прп. Стефана Савваита, творца канонов", kind: "saint", desc: "Прп. Стефан Савваит ‒ монах IX века, подвизавшийся в Лавре св. Саввы в Палестине, творец церковных канонов. Преподобный Стефан Савваит, творец церковных канонов, подвизался в лавре святого Саввы в Палестине в IX веке." },
  { key: "11-10", name: "свт. Арсения I, архиепископа Сербского", kind: "saint", desc: "Свт. Арсений Сербский (XIII в.) ‒ ближайший ученик и преемник св. Саввы Сербского. По его благословению перенёс кафедру Сербской архиепископии в город Печ (Косово), основав там монастырь." },
  { key: "11-10", name: "прп. Иова, игумена Почаевского", kind: "saint", desc: "Прп. Иов Почаевский (в миру Иван Железо, XVI–XVII вв.) ‒ игумен Почаевской лавры. С юности посвятил себя монашеской жизни. Активно защищал православие от католического влияния и унии." },
  { key: "11-10", name: "свт. Димитрия, митрополита Ростовского", kind: "saint", desc: "Свт. Димитрий Ростовский (1651–1709), в миру Даниил Туптало, ‒ выдающийся церковный деятель, проповедник и агиограф. Приняв монашество, он более 20 лет посвятил созданию Четьих-Миней ‒ сборника житий святых, ставшего главным трудом его жизни." },
  { key: "11-10", name: "Прп. Феофила Киевского, Христа ради юродивого", kind: "saint", desc: "Прп. Феофил Киевский (1788–1853), в миру Фома, в детстве был чудесно спасён от гибели — его топили в реке и бросали под мельничное колесо, но Бог хранил младенца." },
  { key: "11-10", name: "сщмч. Кириака, патриарха Иерусалимского", kind: "saint", desc: "Сщмч. Кириак, патриарх Иерусалимский, первоначально был иудеем, указавшим святой Елене место обретения Животворящего Креста Господня. Присутствие при этом чуде привело его к искренней вере во Христа и крещению." },
  { key: "11-10", name: "прп. Иоанна Хозевита, епископа Кесарийского", kind: "saint", desc: "Прп. Иоанн Хозевит, епископ Кесарийский (VI в.), родился в египетских Фивах. С юности подвизался в Фиваидской пустыне. Был поставлен епископом Кесарии Палестинской, но, стремясь к уединению, оставил кафедру и удалился в Хузевскую пустыню близ Иерусалима." },
  { key: "11-10", name: "сщмч. Неофита, епископа Урбнисского (VII)", kind: "saint", desc: "Сщмч. Неофит, епископ Урбнисский, был персидским военачальником Омаром, который во время вторжения в Грузию в VI веке у Шиомгвимского монастыря увидел ангельский сонм и святого Шио." },
  { key: "11-10", name: "прп. Арсения Каппадокийского, архимандрита", kind: "saint", desc: "Прп. Арсений Каппадокийский (ок. 1840-1924) родился в каппадокийском селе Фараса. Приняв монашество и священный сан, 55 лет он окормлял свою паству, прославившись даром чудотворения и исцеления, которые проявлялись как к христианам, так и к мусульманам." },
  { key: "11-10", name: "Сщмч. Иоанна Вилинского, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Вилинский (1857-1918) родился в Ярославской губернии, окончил духовную семинарию и с 1882 года служил священником в селе Трофимовское. 10 ноября 1918 года он был без суда расстрелян чекистами вместе с другими арестованными во вр" },
  { key: "11-10", name: "прмч. Геннадия (Парфентьева), архимандрита", kind: "saint", desc: "Прмч. Геннадий (Парфентьев, 1864-1919), настоятель Яранского Пророчицкого монастыря, происходил из крестьян Курской губернии. Приняв монашество в 1896 году, он прошёл путь от послушника до игумена." },
  { key: "11-11", name: "Прмц. Анастасии Римляныни", kind: "saint", desc: "Прмц. Анастасия Римляныня, осиротев в три года, была воспитана в монастыре близ Рима, в котором приняла иночество. Во время гонений императора Декия (249-251 гг.), когда ей был 21 год, её за исповедание христианской веры схватили и привели к правителю." },
  { key: "11-11", name: "прп. Авраамия, архимандрита Ростовского", kind: "saint", desc: "Прп. Аврамий Ростовский, приняв в юности иночество, поселился на берегу озера Неро. В языческом Ростове он активно проповедовал христианство. По явлению ап." },
  { key: "11-11", name: "прп. Анны (Евфимиана)", kind: "saint", desc: "Прп. Анна (VIII-IX вв.) – византийская подвижница, принявшая мужской монашеский образ под именем Евфимиан. После смерти мужа, вместе со своим сыном св." },
  { key: "11-11", name: "Сщмч. Николая Пробатова, пресвитера и с ним", kind: "saint", desc: "Сщмч. Николай Пробатов (1874-1918), выпускник Тамбовской духовной семинарии, служил священником в селе Агломазово. Активно занимался просвещением, построил школу и обновил храм." },
  { key: "11-11", name: "сщмч. Иоанна Рудинского, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Рудинский (1867-1930), выпускник Ярославской духовной семинарии, служил священником в родном селе Покровское-на-Сити. Неоднократно преследовался советской властью: арестовывался в 1920, 1926 и 1929 годах по различным обвинениям." },
  { key: "11-11", name: "сщмч. Евгения Ивашко, пресвитера", kind: "saint", desc: "Сщмч. Евгений Ивашко (1899-1937) окончил Минскую духовную семинарию. Рукоположен в священники в 1924 году, служил в различных приходах Белоруссии и России." },
  { key: "11-11", name: "мц. Анастасии Лебедевой", kind: "saint", desc: "Мц. Анастасия Лебедева (1899 – после 1937) родилась в крестьянской семье в Ярославской губернии. После смерти мужа в 1930 году, оставшись с тремя детьми, вела хозяйство одна, но была вынуждена вступить в колхоз после обложения непосильным налогом." },
  { key: "11-11", name: "сщмч. Леонида Муравьева, пресвитера", kind: "saint", desc: "Сщмч. Леонид Муравьев, родившийся в 1868 году, окончил Московскую духовную семинарию и с 1896 года служил в Крестовоздвиженской церкви села Марьинка. В 1931 году он был ложно обвинен в нанесении ущерба колхозу, но дело развалилось." },
  { key: "11-12", name: "Тертия", kind: "saint", desc: "Св. апостол Тертий (I в.) ‒ один из 70 учеников Христа, ближайший сотрудник апостола Павла. Лично записал Послание к Римлянам (Рим.16:22), так как апостол Павел имел неразборчивый почерк." },
  { key: "11-12", name: "Варсавы", kind: "saint", desc: "Сын Иосифа Обручника, был одним из двух учеников Христовых, избираемых на апостольство вместо Иуды Искариота, но не был избран, так как жребий пал на апостола Матфия (Деян.1:23-26)." },
  { key: "11-12", name: "и Артемы", kind: "saint", desc: "Св. Артема, один из апостолов от 70-ти, упомянут апостолом Павлом в Послании к Титу (3:12) как доверенный спутник. Он был рукоположен во епископа Листры (Малая Азия), где ревностно проповедовал Евангелие и утверждал христианскую веру." },
  { key: "11-12", name: "сщмч. Маркиана, епископа Сиракузского", kind: "saint", desc: "Сщмч. Маркиан, бывший последователь Симона Волхва, почитается как первый епископ Сиракузский, обращенный в христианство через апостола Петра. Около 39 года он был направлен на проповедь в Сицилию, где основал христианскую общину в пещере близ Сиракуз." },
  { key: "11-12", name: "мц. Евтропии Александрийской", kind: "saint", desc: "Мученица Евтропия приняла смерть за Христа в Александрии около 250 года. Подвиг её заключался в духовной поддержке заключённых христиан – она регулярно посещала темницы, укрепляя узников." },
  { key: "11-12", name: "прмц. Анастасии Солунской", kind: "saint", desc: "Прмц. Анастасия Римляныня, осиротев в три года, была воспитана в монастыре близ Рима, в котором приняла иночество. Во время гонений императора Декия (249-251 гг.), когда ей был 21 год, её за исповедание христианской веры схватили и привели к правителю." },
  { key: "11-12", name: "Сщмч. Матфея Казарина, протодиакона", kind: "saint", desc: "Сщмч. протодиакон Матфей Казарин (1886-1942) обучался в Тамбовской духовной семинарии. Неоднократно подвергался репрессиям: в 1930 году был осуждён на 2 года лагерей." },
  { key: "11-12", name: "Обретение мощей свт. Агафангела (Преображенского), исп., митрополита Ярославского", kind: "saint", desc: "Исп. Агафангел (Преображенский, 1854–1928), митрополит Ярославский, родился в семье священника, с юности стремился к служению Церкви. Окончил Тульскую духовную семинарию и Московскую духовную академию." },
  { key: "11-12", name: "Озерянская", year: "XVI", kind: "saint", desc: "Недалеко от Харькова, в Преображенском Куряжском монастыре хранился чудотворный образ Божией Матери Озерянской. По преданию, образ был явлен в конце XVI века возле села Озеряны – отсюда и название иконы; впоследствии на этом месте возникла обитель, также получившая название Озерянской." },
  { key: "11-13", name: "мч. Епимаха Нового", kind: "saint", desc: "Св. мученик Епимах, египетский отшельник с горы Пелусийской, во время гонений в Александрии (ок. 250 г.) публично разрушил языческих идолов, исповедав христианство." },
  { key: "11-13", name: "прп. Мавры Константинопольской, диаконисы", kind: "saint", desc: "Преподобная Мавра подвизалась в Царьграде, где основала обитель, в которой и скончалась в V веке. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Соо" },
  { key: "11-13", name: "Сщмч. Иоанна Кочурова, пресвитера Царскосельского", kind: "saint", desc: "Сщмч. протоиерей Иоанн Кочуров (1871-1917) родился в семье рязанского священника, окончил Санкт-Петербургскую Духовную Академию. Двенадцать лет служил миссионером в США." },
  { key: "11-13", name: "прмч. Леонида (Молчанова), игумена", kind: "saint", desc: "Прмч. Леонид (Молчанов, 1872-1918) был игуменом Сольвычегодского Введенского монастыря в Вологодской губернии. 13 ноября 1918 года он был расстрелян советской властью за веру." },
  { key: "11-13", name: "Всеволода Смирнова", kind: "saint", desc: "Сщмч. Всеволод Смирнов (1874-1937), сын священника, окончил Московскую духовную семинарию. Служил в Успенской церкви села Дерменцово. В 1929 году арестован за проповедь, истолкованную как антисоветская агитация, и сослан на три года в Архангельскую область." },
  { key: "11-13", name: "Александра Воздвиженского", kind: "saint", desc: "Сщмч. Александр Воздвиженский (1876-1937), сын диакона, окончил Вифанскую духовную семинарию. С 1903 года служил священником в храмах Московской губернии, с 1935 года – протоиерей Никольской церкви в селе Ново-Загарье." },
  { key: "11-13", name: "Сергия Розанова", kind: "saint", desc: "Сщмч. Сергий Розанов (1905-1937), сын псаломщика, служил в храмах Дмитровского района Подмосковья. В октябре 1937 года арестован по обвинению в контрреволюционной деятельности и антисоветской агитации." },
  { key: "11-13", name: "Алексия Сибирского", kind: "saint", desc: "Сщмч. Алексий Сибирский (1870-1937), сын священника, окончил Тверскую духовную семинарию и служил в храме родного села Козлово Тверской губернии. В 1929 году был арестован за невыполнение хлебозаготовок и осуждён на год лагерей и два года ссылки." },
  { key: "11-13", name: "Василия Архангельского", kind: "saint", desc: "Сщмч. Василий Архангельский (1864-1937) окончил Московскую духовную семинарию. С 1885 года служил священником. В 1920 году был арестован и условно осуждён." },
  { key: "11-13", name: "Петра Воскобойникова", kind: "saint", desc: "Сщмч. Петр Воскобойников (1867-1937), сын священника, окончил Тульскую духовную семинарию. Всю жизнь прослужил в Казанском храме села Баткополье, где ранее служил его отец." },
  { key: "11-13", name: "Василия Колоколова", kind: "saint", desc: "Сщмч. Василий Колоколов (1873-1937) с 1900 года служил священником в Иоанно-Предтеченском храме села Грибаново Московской губернии. Неоднократно подвергался репрессиям: в 1922 году осужден условно по делу об изъятии ценностей, в 1929 году приговорен к ссылке за невыполнение хлебозаготовок." },
  { key: "11-13", name: "Анатолия", kind: "saint", desc: "Прмч. Анатолий (Ботвинников, 1881-1937), уроженец Могилевской губернии, участник Русско-японской войны. После плена принял монашество, служил в Николо-Теребенском монастыре." },
  { key: "11-13", name: "Евфросина (Антонова), иеромонахов", kind: "saint", desc: "Прмч. Евфросин (Антонов, 1885-1937) родился в крестьянской семье. Принял постриг в Спасо-Елеазарьевской пустыни, в 1922 году рукоположен в иеромонаха. После закрытия монастырей служил в подмосковных храмах, окормляя монашествующих." },
  { key: "11-13", name: "мч. Иакова Блатова", kind: "saint", desc: "Мученик Иаков Блатов (1880-1937), крестьянин из села Старое Московской губернии, до революции содержал в Москве портновскую мастерскую. После 1917 года вернулся в село, где активно участвовал в церковной жизни: был казначеем, а затем председателем церковного совета храма." },
  { key: "11-14", name: "Иоанна, епископа", kind: "saint", desc: "Сщмч. Иоанн, епископ Персидский, принял мученическую смерть во время гонений на христиан в Персии при царе Сапоре II в 343 году – был побит камнями. Он пострадал вместе с множеством верующих." },
  { key: "11-14", name: "Иакова Ревнителя, пресвитера, в Персии пострадавших", kind: "saint", desc: "Священномученик Иаков Ревнитель пострадал в гонение персидского царя Шапура II около &dagger; 345 года. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопк" },
  { key: "11-14", name: "мч. Ерминингельда, царевича Готфского", kind: "saint", desc: "Св. мученик Ерминингельд, царевич Готфский, принял мученическую смерть в 586 году. Оставив арианскую ересь, он обратился в православие, несмотря на уговоры и угрозы своего отца-арианина, короля Лувингильда." },
  { key: "11-14", name: "Александра Смирнова", kind: "saint", desc: "Сщмчч. Александр Смирнов и Феодор Лебедев были священниками соседних храмов в селе Вышегород Московской губернии. 14 ноября 1918 года они были арестованы карательным отрядом латышей." },
  { key: "11-14", name: "Феодора Лебедева", kind: "saint", desc: "Сщмчч. Александр Смирнов и Феодор Лебедев были священниками соседних храмов в селе Вышегород Московской губернии. 14 ноября 1918 года они были арестованы карательным отрядом латышей." },
  { key: "11-14", name: "Александра Шалая", kind: "saint", desc: "Сщмч. Александр Шалай (1879-1937) родился в Слуцке, служил в храмах Минской епархии, в 1930-х годах был настоятелем Свято-Троицкой церкви в селе Блонь." },
  { key: "11-14", name: "Димитрия Овечкина", kind: "saint", desc: "Сщмч. Димитрий Овечкин (1877-1937) окончил Казанскую учительскую семинарию. После нескольких лет преподавания принял сан священника и служил в соборах города Оса." },
  { key: "11-14", name: "мц. Елисаветы Самосской", kind: "saint", desc: "Мц. Елисавета Самосская (1860-1937) родилась в Нижнем Новгороде. Окончив Мариинский институт в Москве, работала частным преподавателем французского и немецкого языков." },
  { key: "11-14", name: "мч. Петра Игнатова", kind: "saint", desc: "Мч. Петр Игнатов (1904-1941) родился в Калужской губернии. После службы в войсках ОГПУ поселился с женой Анастасией в Кунцеве, работая сторожем. Под влиянием глубоко верующей супруги Петр полностью посвятил себя православной вере, вёл аскетический образ жизни, регулярно посещал храм." },
  { key: "11-15", name: "Прп. Маркиана Кирского (Киринейского)", kind: "saint", desc: "Прп. Маркиан (IV век) – подвижник, проведший жизнь в строгом пустынном затворе. Его келия по ночам озарялась Божественным светом во время молитв. Со временем он принял двух учеников, но продолжал жить в уединении." },
  { key: "11-15", name: "Одигитрия Шуйская", year: "1654–1655", kind: "saint", desc: "Шуйская-Смоленская икона – поясное изображение Божией Матери с Младенцем Христом на руках. Спаситель сидит справа на левой руке Богоматери. Иконографической особенностью Шуйской иконы, отличающей ее от других икон Одигитрии, является характ" },
  { key: "11-16", name: "Обновление храма вмч. Георгия в Лидде", kind: "saint", desc: "Вмч. Георгий Победоносец, римский военачальник III-IV веков, родился в Палестине. При императоре Диоклетиане он открыто исповедал свою веру во Христа, раздал имущество бедным и обличил жестокость гонителей.", lifeId: "georgiy" },
  { key: "11-16", name: "прп. Акепсима Антиохийского", kind: "saint", desc: "Прп. Акепсим Антиохийский был отшельником, 60 лет подвизавшимся в сирийской пустыне близ города Кирра. По повелению патриарха он вышел из затвора и был поставлен во епископа." },
  { key: "11-16", name: "прав. Снандулии (Яздундокты) Персидской", kind: "saint", desc: "Мц. Яздундокта, мирянка из Ктесифона (Персия), прославилась подвигом милосердия во время гонений на христиан при царе Сапоре. Когда более ста верующих были заключены в тюрьму и приговорены к казни, она ежедневно кормила узников, спасая их от голода." },
  { key: "11-16", name: "Сщмч. Николая Динариева, пресвитера", kind: "saint", desc: "Сщмч. Николай Динариев был настоятелем храма в селе Данево Рязанской губернии. Вскоре после революции, в 1918 году, отец Николай был арестован и расстрелян у стен городского кладбища в Касимове вместе со священником Матфием Рябцевым." },
  { key: "11-16", name: "мч. Павла Парфенова", kind: "saint", desc: "Мч. Павел Парфёнов занимался торговлей и был церковным старостой митинского храма Касимовского уезда. Он помогал односельчанам, работавшим на фабрике за нищенскую плату, часто прощая их долги." },
  { key: "11-16", name: "Василия Архангельского", kind: "saint", desc: "Сщмч. Василий Архангельский (1874-1937) родился в Тульской губернии. После рукоположения служил священником, в последние годы – в храме села Люблино Московской области." },
  { key: "11-16", name: "Петра Орленкова", kind: "saint", desc: "Сщмч. Петр Орленков (1876-1937) служил в храмах Московской епархии. В октябре 1937 года арестован по обвинению в контрреволюционной агитации. На допросах виновным себя не признал." },
  { key: "11-16", name: "Василия Покровского", kind: "saint", desc: "Сщмч. Василий Покровский (1875-1937) окончил Владимирскую духовную семинарию, был рукоположен в сан священника и служил в храме села Гольцово, а позднее – в селе Пустое Рождество Московской области." },
  { key: "11-16", name: "Александра Зверева", kind: "saint", desc: "Сщмч. Александр Зверев (1881-1937) окончил Московскую духовную академию. С 1919 года служил настоятелем Никольского храма в Звонарях (Москва). Дважды репрессирован: в 1922 году осуждён за сопротивление изъятию церковных ценностей, в 1933 году – за отказ от сотрудничества с ОГПУ, сослан в Каргополь." },
  { key: "11-16", name: "Владимира Писарева", kind: "saint", desc: "Сщмч. Владимир Писарев (1881-1937) родился в Московской губернии. Рукоположен в диакона в 1911 году, служил в Тихвинском храме села Костино. В 1930 году стал священником." },
  { key: "11-16", name: "Сергия Кедрова", kind: "saint", desc: "Сщмч. Сергий Кедров (1880-1937) окончил Московскую духовную семинарию, с 1908 года служил священником в Троицком храме села Фаустово, где также заведовал церковноприходской школой." },
  { key: "11-16", name: "Николая Пятницкого", kind: "saint", desc: "Сщмч. Николай Пятницкий (1884-1937) после духовного училища служил псаломщиком, в 1913 году рукоположен в священника в Тюмени. В 1931 году арестован ОГПУ, после освобождения переехал в Московскую область." },
  { key: "11-16", name: "Викентия Смирнова", kind: "saint", desc: "Сщмч. Викентий Смирнов (1881-1937) родился в Московской губернии, окончил духовную семинарию. Рукоположен в священника, за безупречную службу возведён в сан протоиерея и в 1930 году назначен настоятелем храма в посёлке Химки." },
  { key: "11-16", name: "Иоанна Кесарийского", kind: "saint", desc: "Сщмч. Иоанн Кесарийский (1878-1937) служил в храмах Московской епархии, в последние годы – настоятелем Владимирской церкви села Быково. В ноябре 1937 года арестован вместе с клиром и активными мирянами по обвинению в создании «контрреволюционной группы»." },
  { key: "11-17", name: "Прп. Иоанникия Великого", kind: "saint", desc: "Прп. Иоанникий Великий (752-846) родился в Вифинии в бедной семье. В юности служил в императорском войске, но, стремясь к духовной жизни, оставил мир. Став монахом, он более 70 лет провёл в аскетических подвигах: жил в уединённых пустынях, монастырях и затворах, предаваясь строгому посту и непрестанной молитве." },
  { key: "11-17", name: "Прп. Меркурия, постника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Меркурий Печерский, постник, подвизался в Киево-Печерском монастыре в XIV веке. Он известен своим духовным союзом с прп. Паисием – святые были неразлучны, жили в одной келье и после смерти были погребены в общем гробу." },
  { key: "11-17", name: "прп. Никандра Городноезерского", kind: "saint", desc: "Прп. Никандр Городноезерский, подвижник XVII века, возродил пустынную обитель на берегу озера Городно (близ современных Боровичей). Он основал скит на месте древнего Воскресенского монастыря, который к тому времени пришёл в упадок – согласно описи 1581 года, там оставалось лишь три насельника." },
  { key: "11-17", name: "блж. Симона, Христа ради юродивого, Юрьевецкого", kind: "saint", desc: "Блж. Симон Юрьевецкий, Христа ради юродивый, родился в Костромской губернии. С юности оставил дом и поселился в лесах близ села Елнать, приняв подвиг юродства." },
  { key: "11-17", name: "Св. Николая Виноградова, исп., пресвитера", kind: "saint", desc: "Исп. Николай Виноградов (1873-1931) родился в Клину. Окончив Московскую духовную семинарию в 1896 году, он преподавал в церковноприходской школе, а в 1898 году был рукоположен в священника к Смоленскому храму села Данилово Подольского уезда, где прослужил 32 года." },
  { key: "11-17", name: "прмц. Евгении (Лысовой), монахини", kind: "saint", desc: "Прмц. Евгения (Лысова, 1892-1935) родилась в Рязанской губернии. Приняла монашеский постриг в 1926 году. В 1931 году была арестована за участие в проводах арестованных монахинь и приговорена к 3 годам ссылки в Казахстан." },
  { key: "11-17", name: "сщмч. Александра Петропавловского, пресвитера", kind: "saint", desc: "Сщмч. Александр Петропавловский (1884-1937) происходил из дворянской семьи. В 1929 году рукоположен в священника, служил в храмах Ярославской области. Неоднократно подвергался гонениям: в 1930 году у семьи конфисковали имущество, что привело к смерти двоих детей." },
  { key: "11-17", name: "сщмч. Исмаила Базилевского, пресвитера", kind: "saint", desc: "Сщмч. Измаил Базилевский (1881-1941) родился в Воронежской губернии. Окончил духовную семинарию, работал учителем, в 1915 году рукоположен в священника." },
  { key: "11-18", name: "свт. Ионы, архиепископа Новгородского", kind: "saint", desc: "Свт. Иона, архиепископ Новгородский (конец XIV в. – 1470) родился в Новгороде и рано осиротел. Принял монашество в Отенской пустыни, где за святую жизнь был избран игуменом." },
  { key: "11-18", name: "свт. Тихона, патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Тихон (Беллавин, 1865–1925) – одиннадцатый Патриарх Московский и всея Руси. Принял монашество в 1891 году. Управлял епархиями в Северной Америке, Ярославле, Вильно, проявляя особую заботу о пастве." },
  { key: "11-18", name: "Отцов Поместного Собора Церкви Русской 1917–1918 годов", kind: "feast", desc: "4 мая 2017 года на заседании Священного Синода был установлен день памяти Отцов Поместного Собора Церкви Русской 1917–1918 гг. – 18 ноября, день избрания святителя Тихона (Белавина) на Московский Патриарший престол." },
  { key: "11-18", name: "Патрова", kind: "saint", desc: "Св. апостол Патров упоминается апостолом Павлом в Послании к Римлянам (16:14). В библейской энциклопедии архим. Никифора сказано: \"Патров – один из 70 апостолов и ревностнейший из спутников и сотрудников ап." },
  { key: "11-18", name: "Филолога", kind: "saint", desc: "Апостол от 70-ти Филолог упоминается св. Павлом в Послании к Римлянам (16:15). Существует две основные версии его жития. По римскому преданию, он был знатным римлянином, обращённым апостолом Павлом, и принял мученическую смерть вместе с супругой Юлией при императоре Нероне." },
  { key: "11-18", name: "свт. Григория, архиепископа Александрийского", kind: "saint", desc: "Свт. Григорий, архиепископ Александрийский, с юности посвятил себя служению Богу. Будучи избран на кафедру, он стал образцом пастыря. При иконоборце императоре Льве V (813–820) святитель явился в Константинополь и смело обличил его в ереси." },
  { key: "11-18", name: "Сщмч. Гавриила Масленникова, пресвитера", kind: "saint", desc: "Сщмч. Гавриил Масленников (1871-1937) родился в Рязанской губернии. Участник русско-японской войны, георгиевский кавалер. В 1925 году, оставив профессию кузнеца из-за проблем со зрением, был рукоположен в священника." },
  { key: "11-19", name: "Сщмч. Павла I, патриарха Константинопольского", kind: "saint", desc: "Сщмч. Павел был избран патриархом Константинопольским в 340 году в разгар арианских споров. Несмотря на поддержку православной паствы, он трижды изгонялся из столицы императором-арианином Констанцием." },
  { key: "11-19", name: "прп. Варлаама Хутынского", kind: "saint", desc: "Прп. Варлаам Хутынский (XII в.) был сыном знатного новгородца. Оставив мирскую жизнь, он поселился в уединённом месте Хутынь близ Новгорода, где вёл суровую подвижническую жизнь." },
  { key: "11-19", name: "Прп. Луки, иконома Печерского, в Ближних пещерах", kind: "icon", desc: "Прп. Лука Печерский подвизался в Киево-Печерском монастыре в XIII в., исполнял послушание эконома. Больше о его жизни ничего не известно. Мощи его почивают в Ближних (Антониевых) пещерах." },
  { key: "11-19", name: "свт. Германа, архиепископа Казанского", kind: "saint", desc: "Свт. Герман Казанский (XVI в.), происходивший из боярского рода Полевых, начал монашеский путь в Иосифо-Волоколамском монастыре под руководством св. Гурия." },
  { key: "11-19", name: "прп. Варлаама Керетского, иеромонаха", kind: "saint", desc: "Прп. Варлаам Керетский (XVI век) был священником в Коле, но, введённый бесом в заблуждение, совершил убийство невинной жены. Для искупления тяжкого греха он совершил многолетнее покаянное плавание в лодке с телом супруги по Белому морю, непрестанно молясь." },
  { key: "11-19", name: "прп. Луки Тавроменийского", kind: "saint", desc: "Прп. Лука Тавроменийский, сицилийский подвижник IX века, в юности оставил мирскую жизнь и удалился в пустыню. Многие годы он провёл в на горе Этна, предаваясь посту и молитве." },
  { key: "11-19", name: "Никиты (Делекторского), епископа Орехово-Зуевского", kind: "saint", desc: "Сщмч. Никита (Делекторский, 1876-1937) родился во Владимирской губернии. Окончил Московскую духовную академию, служил священником, а в 1924 году принял монашество и был хиротонисан во епископа Бугульминского." },
  { key: "11-19", name: "Анатолия Бержицкого", kind: "saint", desc: "Сщмч. Анатолий Бержицкий (1875-1937) родился в Херсонской губернии. Получил юридическое и духовное образование, принял священный сан после 1917 года. Неоднократно подвергался арестам: в 1921 и 1930 годах." },
  { key: "11-19", name: "Арсения Троицкого", kind: "saint", desc: "Сщмч. Арсений Троицкий (1880-1937) служил в селе Селихово Тверской губернии. После революции противостоял обновленческому расколу, за что в 1923 году был арестован и сослан в Соловецкий лагерь на 3 года." },
  { key: "11-19", name: "Николая Дворицкого", kind: "saint", desc: "Сщмч. Николай Дворицкий (1878–1937) родился в Псковской губернии. В 20 лет, что было редкостью, стал диаконом в селе Дно. В 1911 году переведён в Новгород." },
  { key: "11-19", name: "Николая Протасова", kind: "saint", desc: "Сщмч. Николай Протасов (1867–1937) родился в семье священника. Окончил Тульскую духовную семинарию и был рукоположен в 1890 году. В период гонений был неоднократно арестован." },
  { key: "11-19", name: "Константина Любомудрова", kind: "saint", desc: "Сщмч. Константин Любомудров (1879–1937), сын псаломщика, получил духовное образование и стал священником в 1908 году. Овдовев, он поступил в Московскую духовную академию и Археологический институт." },
  { key: "11-19", name: "Варлаама (Никольского), игумена", kind: "saint", desc: "Прмч. Варлаам (Никольский, 1872–1937) родился в Тульской губернии. Приняв постриг в московском Чудовом монастыре, он был рукоположен в иеромонаха. После революции служил в московских храмах." },
  { key: "11-19", name: "Гавриила", kind: "saint", desc: "Прмч. Гавриил (Владимиров, 1873–1937) родился в псковской крестьянской семье. Приняв постриг на Афоне, служил полковым священником. После революции работал лектором, но был уволен за отказ снять сан." },
  { key: "11-20", name: "прп. Лазаря Галисийского, иеромонаха", kind: "saint", desc: "Прп. Лазарь Галисийский (†1053) родился в Малой Азии, принял монашество в Палестинской лавре св. Саввы. После 10 лет подвижничества вернулся на родину и поселился на горе Галисийской близ Эфеса, где удостоился видения огненного столпа с ангельским пением." },
  { key: "11-20", name: "Прп. Зосимы Ворбозомского", kind: "saint", desc: "Прп. Зосима Ворбозомский, живший на рубеже XV–XVI веков, основал Благовещенский монастырь на острове Ворбозомского озера под Белозерском. Эта обитель входила в число малых пустынных монастырей «Заволжья», группировавшихся вокруг Кирилло-Белозерского монастыря." },
  { key: "11-20", name: "Обретение мощей прп. Кирилла Новоезерского (Новгородского)", kind: "saint", desc: "Прп. Кирилл Белый, Новоезерский (Новгородский), уроженец Галича, с юности стремился к монашеству. Тайно уйдя из дома, он принял постриг в обители прп. Корнилия Комельского, где его нашли родители, также принявшие иночество." },
  { key: "11-20", name: "мч. Феодота Анкирского, корчемника", kind: "saint", desc: "Св. мч. Феодот и семь дев-мучениц пострадали за веру в Анкире в начале IV века. Феодот, владелец гостиницы, беседами приводил язычников к христианской вере, помогал христианам во время гонений, хоронил мучеников." },
  { key: "11-20", name: "Кирилла (Смирнова), митрополита Казанского", kind: "saint", desc: "Сщмч. Кирилл (Смирнов), митрополит Казанский (1863–1937), – один из виднейших иерархов Русской Церкви XX века. Выпускник Санкт-Петербургской Духовной академии, он принял монашество после личной трагедии – смерти дочери и супруги." },
  { key: "11-20", name: "Михаила Адамонтова", kind: "saint", desc: "Сщмч. Михаил Адамонтов родился в 1892 году в Нижегородской губернии. Служил в селе Берендеевка Лысковского района. В сентябре 1937 года арестован и вскоре расстрелян." },
  { key: "11-20", name: "Александра Ильинского", kind: "saint", desc: "В октябре 1937 года в Перевозском районе Нижегородской области были арестованы четыре священника: Александр Ильинский (род. 1899), Александр Курмышский (род." },
  { key: "11-20", name: "Александра Курмышского", kind: "saint", desc: "Сщмч. Александр Курмышский родился в 1879 году в Симбирске. Окончил духовную семинарию и служил в храме села Танайково Перевозского района Нижегородской области." },
  { key: "11-20", name: "Михаила Гусева", kind: "saint", desc: "Сщмч. Михаил Гусев (1890–1937) родился в семье священника Серафимо-Дивеевского монастыря. Был рукоположен в 1913 году и служил в этой обители до её закрытия в 1927 году." },
  { key: "11-20", name: "Александра Крылова", kind: "saint", desc: "Александр Иванович Крылов (1879 г.р.), священник из села Ляпуны Нижегородской области, был арестован в сентябре 1937 года. Его ложно обвинили в поджогах домов, скирды соломы и мельницы." },
  { key: "11-20", name: "Николая Романовского", kind: "saint", desc: "Сщмч. Николай Романовский (1869-1937) родился в Херсонской губернии. Служил в Николаеве, преподавал Закон Божий в женской гимназии, а во время Первой мировой войны организовал госпиталь для раненых." },
  { key: "11-20", name: "Алексия Молчанова", kind: "saint", desc: "В сентябре 1937 года в Нижегородской области были арестованы диакон Иоанн Мошков (село Исады), диакон Вениамин Владимирский (село Просек) и верующая Елизавета Сидорова (село Ивановское)." },
  { key: "11-20", name: "Павла Борисоглебского", kind: "saint", desc: "Сщмч. Павел Борисоглебский служил в селе Плотинское Нижегородской области. Он был арестован в июле 1937 года по обвинению в антисоветских высказываниях, которые якобы допускал во время ссылки в 1930-1931 годах." },
  { key: "11-20", name: "Василия Краснова", kind: "saint", desc: "Сщмч. Василий Краснов (1886-1937) родился в Самарской губернии. Окончив 4 класса семинарии, служил псаломщиком, участвовал в Первой мировой и Гражданской войнах." },
  { key: "11-21", name: "Собор Архистратига Михаила и прочих Небесных Сил бесплотных", kind: "feast", desc: "Празднование Собора Архистратига Божия Михаила и прочих Небесных Сил бесплотных установлено в начале IV века на Поместном Лаодикийском Соборе, бывшем за несколько лет до Первого Вселенского Собора.", lifeId: "arhangel-mihail" },
  { key: "11-21", name: "Архангелов Гавриила", kind: "saint", desc: "Архангел Гавриил – один из главных вестников Божиих в истории спасения человечества. Именно он принёс Деве Марии Благую весть о рождении Сына Божьего – Иисуса Христа." },
  { key: "11-21", name: "Рафаила", kind: "saint", desc: "Архангел Рафаил, чьё имя означает «исцеление Божие», известен как врач недугов человеческих, утешитель скорбящих и путеводитель из библейской Книги Товита." },
  { key: "11-21", name: "Уриила", kind: "saint", desc: "Архангел Уриил, чье имя означает свет или огонь Божий, является просветителем потемнённых и наставником заблудших. О нём пишется в Третьей книге Ездры (3Езд.4:1-50)." },
  { key: "11-21", name: "Селафиила", kind: "saint", desc: "Архангел Селафиил ‒ «молитвенник Божий», побуждающий людей к молитве. Он явился Агари в пустыне, когда она, изгнанная Авраамом, молилась в отчаянии о своем сыне Измаиле (Быт.16:11)." },
  { key: "11-21", name: "Иегудиила", kind: "saint", desc: "Архангел Иегудиил, чье имя означает «славящий Бога», почитается как покровитель всех, кто трудится для славы Божией. Он укрепляет подвизающихся и монашествующих, ходатайствует о воздаянии за их подвиги." },
  { key: "11-21", name: "Варахиила", kind: "saint", desc: "Архангел Варахиил, чье имя означает «благословение Божие», известен по церковному Преданию как податель Божьих благословений на всякое доброе дело и житейское занятие." },
  { key: "11-21", name: "Иеремиила", kind: "saint", desc: "Архангел Иеремиил, чье имя означает «возвышение к Богу», известен как внушитель благих помыслов и возноситель душ к Богу. О нём пишется в 3-й книге Ездры (3Езд.4:35-37)." },
  { key: "11-22", name: "прп. Матроны Константинопольской", kind: "saint", desc: "Прп. Матрона Константинопольская (ок. 492), стремясь к монашеской жизни, тайно оставила семью и, выдав себя за евнуха Вавилу, поступила в мужской монастырь.", lifeId: "matrona" },
  { key: "11-22", name: "прп. Феоктисты Паросской", kind: "saint", desc: "Прп. Феоктиста в 18 лет была захвачена арабами, но бежала на пустынный остров Парос, где 35 лет прожила в полном уединении в заброшенном храме, питаясь семенами подсолнечника." },
  { key: "11-22", name: "Прп. Онисифора Печерского, в Ближних пещерах, иеромонаха", kind: "saint", desc: "Прп. Онисифор, иеромонах Киево-Печерского монастыря, сподобился от Бога дара прозорливости, видя грехи человеческие. Согласно сказанию, его молитва остановила смрад, исходивший от тела скоропостижно скончавшегося инока." },
  { key: "11-22", name: "мч. Александра Солунского", kind: "saint", desc: "Мч. Александр, пострадавший в начале IV в., был схвачен за исповедание христианской веры. Он не только отказался принести жертву идолам, но и ниспроверг жертвенник, за что был приговорён к усекновению главы." },
  { key: "11-22", name: "мч. Антония Апамейского", kind: "saint", desc: "Мч. Антоний, каменщик из Сирии, пытался обратить своих языческих сограждан от идолопоклонства. Не добившись успеха, он удалился в пустыню, где жил два года." },
  { key: "11-22", name: "прп. Иоанна Колова", kind: "saint", desc: "Прп. Иоанн Колов, подвижник V века, подвизался в египетской пустыне в монастыре прп. Пимена Великого. Начал свой путь с горделивого желания жить «как ангел», без забот о теле, но был вразумлён Господом." },
  { key: "11-22", name: "свт. Нектария Эгинского, митрополита Пентапольского, чудотворца", kind: "saint", desc: "Слава Православия – святые угодники Божии, как новые звезды, вспыхивающие на небосклоне Христовой Церкви. Русь просияла в последние времена тысячами новомучеников и исповедников, и все больше и больше известно нашим верующим имен этих праведников Божьих, стоявших за Истину.", lifeId: "nectariy-eginsky" },
  { key: "11-22", name: "Собор Аланских святых", kind: "feast", desc: "Поименный список Собора Аланских святых утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и наж" },
  { key: "11-22", name: "Парфения (Брянских), епископа Ананьевского", kind: "saint", desc: "Священномученик Парфений (в миру Петр Арсеньевич Брянских), епископ Ананьевский, родился в 1881 году в семье потомственного почетного гражданина Иркутска, работавшего доверенным (управляющим) промышленно-торговой фирмы &quot;Немчинов и сын&quot;." },
  { key: "11-22", name: "Константина Черепанова", kind: "saint", desc: "Константин Васильевич Черепанов родился в Екатеринбургском уезде Пермской губернии в 1878 году. Образование получил в Пермской Духовной семинарии. Был рукоположен во священники к семипалатинскому Воскресенскому собору." },
  { key: "11-22", name: "Димитрия Русинова", kind: "saint", desc: "Священномученик Димитрий родился в 1871 году в селе Куркино Московского уезда Московской губернии в семье священника Владимира Петровича Русинова. Впоследствии отец Владимир за многолетнюю усердную службу был награжден многими церковными наградами и возведен в сан протоиерея." },
  { key: "11-22", name: "Нестора Панина", kind: "saint", desc: "Нестор Прокофьевич Панин родился в 1881 году в городе Семипалатинске. Избрав путь пастыря, он заканчивает Томскую Духовную семинарию и рукополагается к семипалатинскому Воскресенскому собору." },
  { key: "11-22", name: "Феодора Чичканова", kind: "saint", desc: "Священномученик Феодор Чичканов родился 10 февраля 1884 года в небольшом селе Барнаульского уезда в благочестивой семье Павла Васильевича и Надежды Ефимовны Чичкановых." },
  { key: "11-22", name: "Константина Немешаева", kind: "saint", desc: "Священномученик Константин родился 23 ноября 1879 года в селе Песочном Жиздринского уезда Калужской губернии в семье священника Георгия Немешаева. Пойдя по стопам отца, Константин поступил в Калужскую Духовную семинарию." },
  { key: "11-23", name: "Ераста", kind: "saint", desc: "Святой Родион или Иродион, родственник апостола Павла ( Рим.16,11 ), оставил епископскую кафедру в Патрах, чтобы идти в Рим со святым апостолом Петром." },
  { key: "11-23", name: "Олимпа", kind: "saint", desc: "Святой Родион или Иродион, родственник апостола Павла ( Рим.16,11 ), оставил епископскую кафедру в Патрах, чтобы идти в Рим со святым апостолом Петром." },
  { key: "11-23", name: "Родиона", kind: "saint", desc: "Святые Иродион, Агав, Асинкрит, Руф, Флегонт и Ерм принадлежат к числу 70 апостолов, избранных Христом и посланных им на проповедь (память Собора 70 апостолов 4 января)." },
  { key: "11-23", name: "Сосипатра", kind: "saint", desc: "Святой Родион, или Иродион, родственник апостола Павла ( Рим.16,11 ), оставил епископскую кафедру в Патрах, чтобы идти в Рим со святым апостолом Петром." },
  { key: "11-23", name: "Куарта", kind: "saint", desc: "Святой Родион или Иродион, родственник апостола Павла ( Рим.16,11 ), оставил епископскую кафедру в Патрах, чтобы идти в Рим со святым апостолом Петром." },
  { key: "11-23", name: "Тертия (Терентия)", kind: "saint", desc: "Св. апостол Тертий (I в.) ‒ один из 70 учеников Христа, ближайший сотрудник апостола Павла. Лично записал Послание к Римлянам (Рим.16:22), так как апостол Павел имел неразборчивый почерк." },
  { key: "11-23", name: "Мч. Ореста врача", kind: "saint", desc: "Святой мученик Орест жил в конце III века в городе Тиане в Каппадокии во времена императора Диоклитиана и был знающим и искусным врачом. С детских лет святой Орест был воистину добрым христианином." },
  { key: "11-23", name: "сщмч. Милия, епископа Персидского, и двух учеников его", kind: "saint", desc: "Священномученик Милий, епископ Персидский, и два ученика его жили в IV веке. Святой мученик Милий был изгнан язычниками из города Сузы, где занимал епископскую кафедру." },
  { key: "11-23", name: "прп. Феостирикта (Стирикта), иже в Символех", kind: "saint", desc: "Подвизался в IX веке в монастыре Символон в Малой Азии, при горе Олимп, и был защитником святых икон. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку " },
  { key: "11-23", name: "вмч. Константина-Кахи, кн. Грузинского", kind: "saint", desc: "Святой мученик Константин – грузинский князь из Верхней Карталинии. Он прославился в своей стране щедростью к бедным, покровительством церквам и духовенству." },
  { key: "11-23", name: "Колесование вмч. Георгия (303)", kind: "saint", desc: "Вмч. Георгий Победоносец, римский военачальник III-IV веков, родился в Палестине. При императоре Диоклетиане он открыто исповедал свою веру во Христа, раздал имущество бедным и обличил жестокость гонителей.", lifeId: "georgiy" },
  { key: "11-23", name: "Прмч. Нифонта (Выблова), иеромонаха", kind: "saint", desc: "Иеромонах Нифонт родился в 1882 году в городе Ейске в семье небогатого крестьянина Григория Выблова. Когда ему исполнилось десять лет, родители отдали его учиться в двухклассную сельскую школу в городе Ейске, которую он окончил в 1894 году." },
  { key: "11-23", name: "мч. Александра Медема", kind: "saint", desc: "Мученик Александр родился в 1877 году в городе Митаве Курляндской губернии в семье сенатора Антона Людвиговича Медема, занимавшего многие видные государственные посты, в частности губернатора Новгородского." },
  { key: "11-23", name: "Прокопия (Титова), архиепископа Херсонского", kind: "saint", desc: "Священномученик Прокопий (в миру Петр Семенович Титов) родился 25 декабря 1877 года в семье священника города Кузнецка Томской губернии. Когда Петру исполнилось девять лет, он поступил в духовное училище, а затем в семинарию города Томска, которую окончил в 1897 году." },
  { key: "11-24", name: "Вмч. Мины Котуанского (Фригийского)", kind: "saint", desc: "Святой великомученик Мина, родом египтянин, был воином и служил в городе Котуане под началом центуриона Фирмилиана во время царствования императоров Диоклитиана и Максимиана (284–305)." },
  { key: "11-24", name: "мч. Викентия, диакона, Валенсийского", kind: "saint", desc: "Святой мученик Викентий с детства был учеником мудрого пастыря, епископа города Августополя (ныне Сарагосса, Испания), блаженного Валерия. Когда исполнилось время совершеннолетия, добродетельный, образованный и красноречивый Викентий был рукоположен епископом Валерием в диаконы." },
  { key: "11-24", name: "прп. Феодора Студита, исп., игумена, песнописца", kind: "saint", desc: "Родился в 758 г. в Константинополе и получил широкое и разностороннее образование. Глубоко изучив Св. Писание, святой Феодор успешно противостоял еретикам-иконоборцам в диспутах о православной вере." },
  { key: "11-24", name: "блж. Максима Московского, Христа ради юродивого, чудотворца", kind: "saint", desc: "Блж. Максим, Христа ради юродивый, жил в Москве. Летом и зимой он ходил почти нагим, терпя зной и холод, говоря: «Хоть люта зима, но сладок рай». Его поучения слушали все ‒ от князей до бедняков." },
  { key: "11-24", name: "Прп. Мартирия Зеленецкого", kind: "saint", desc: "Родом из Великих Лук, Псковской губернии, святой с юных лет подвизался в Великолуцкой Сергиевой обители. Желая уединенных подвигов, он поселился на острове Зеленом и основал там монастырь." },
  { key: "11-24", name: "мч. Стефана Дечанского, короля Сербского (ок. 1331)", kind: "saint", desc: "Святой Стефан был старшим сыном короля Милутина. Мученической была его земная жизнь, мученической была и кончина. Его отец по наущению мачехи Стефана отослал сына в монастырь Пантократор в Константинополе, приказав ослепить его в дороге." },
  { key: "11-24", name: "Сщмч. Евгения Васильева, пресвитера", kind: "saint", desc: "Священномученик Евгений родился 20 декабря 1892 года в городе Москве в семье священника Василия Васильева. Получив первоначальное духовное образование, он поступил в Московскую Духовную академию, но окончить ее ввиду захвата власти безбожни" },
  { key: "11-25", name: "Свт. Иоанна Милостивого, патриарха Александрийского", kind: "saint", desc: "Святитель Иоанн Милостивый, патриарх Александрийский, родился на Кипре в VI веке в семье знатного вельможи Епифания. По воле родителей вступил в брак и имел детей." },
  { key: "11-25", name: "прп. Нила Постника", kind: "saint", desc: "Святой преподобный Нил Постник, уроженец Константинополя, жил в IV веке и был учеником святого Иоанна Златоуста . Получив прекрасное образование, Нил еще молодым человеком был назначен на важный пост префекта столицы." },
  { key: "11-25", name: "Блж. Иоанна Власатого, Ростовского", kind: "saint", desc: "Блж. Иоанн Власатый, Милостивый, чудотворец, подвизался в Ростове во времена Ивана Грозного. Имел «власы на главе велики», потому и назывался Власатым." },
  { key: "11-25", name: "прор. Ахии Силомлянина", kind: "saint", desc: "Святой пророк Ахия происходил из города Силома [1] и жил в царствование Соломона и Иеровоама [2] . При Соломоне он предсказал Иеровоаму разделение царства Соломонова и отпадение от него десяти колен, образовавших царство Израильское." },
  { key: "11-25", name: "прп. Нила Мироточивого, Афонского", kind: "saint", desc: "Преподобный Нил Мироточивый родился в Греции, в селении, носящем имя святого Петра, Законийской епархии. Воспитывался своим дядей, иеромонахом Макарием." },
  { key: "11-25", name: "Сщмч. Александра Адрианова, пресвитера", kind: "saint", desc: "Священник Александр Адрианов, настоятель Трехсвятительского храма Нижне-Туринского завода Екатеринбургской епархии, был ревностным и достойным пастырем, который много потрудился как законоучитель, храмоздатель, член различных комитетов и обществ." },
  { key: "11-25", name: "Константина Успенского", kind: "saint", desc: "Священномученик Константин родился 9 апреля 1872 года в селе Алексеевском Московской губернии в семье псаломщика Василия Успенского. В 1892 году Константин Васильевич окончил Московскую Духовную семинарию и был назначен учителем Николо-Богоявленского училища." },
  { key: "11-25", name: "Владимира Красновского", kind: "saint", desc: "Священномученик Владимир родился 5 июля 1889 года в селе Измайлово под Москвой в семье псаломщика Платона Красновского; мать его была при храме просвирней." },
  { key: "11-25", name: "Александра Архангельского", kind: "saint", desc: "Священномученик Александр родился 29 июля 1891 года в селе Рыкова Слобода Рязанского уезда Рязанской губернии в семье псаломщика Ивана Архангельского. В 1916 году Александр поступил в Духовную семинарию, но окончить ее не успел, так как началась революция." },
  { key: "11-25", name: "Матфея Алоина", kind: "saint", desc: "Священномученик Матфей родился 1 августа 1879 года в селе Стенькино недалеко от Рязани в семье священника Александра Алоина. После окончания Рязанской Духовной семинарии Матфей Александрович был рукоположен в 1899 году в сан диакона, а в 1909 году в сан священника." },
  { key: "11-25", name: "Димитрия Розанова", kind: "saint", desc: "Священномученик Димитрий родился 15 августа 1890 года в Москве в семье священника Иоанна Петровича Розанова. Отец Иоанн служил в одном из храмов Москвы до самой своей кончины в 1920 году." },
  { key: "11-25", name: "Петра Косминкова", kind: "saint", desc: "Во время гонений на Русскую Православную Церковь бывало, что воинствующие безбожники арестовывали не только священника, но и весь клир, а также членов церковного совета из числа наиболее активных мирян, как это произошло в селе Быково Раменского района." },
  { key: "11-25", name: "Симеона Кречкова, диакона", kind: "saint", desc: "Во время гонений на Русскую Православную Церковь бывало, что воинствующие безбожники арестовывали не только священника, но и весь клир, а также членов церковного совета из числа наиболее активных мирян, как это произошло в селе Быково Раменского района." },
  { key: "11-25", name: "Милостивая", kind: "saint", desc: "Икона Божией Матери, именуемая «Милостивая», (Киккская) написана, по преданию, святым апостолом и евангелистом Лукой . Другое свое наименование «Киккиотиса» (что означает «Пребывающая в Киккосе») икона получила от названия горы Киккос, расположенной на острове Кипр ." },
  { key: "11-26", name: "Свт. Иоанна Златоуста, архиепископа Константинопольского", kind: "saint", desc: "Свт. Иоанн Златоуст, архиепископ Константинопольский (IV–V вв.), ‒ величайший проповедник и богослов, один из трёх вселенских святителей. Прославился красноречием, толкованиями Св.", lifeId: "ioann-zlatoust" },
  { key: "11-26", name: "мц. Манефы Кесарийской (Палестинской)", kind: "saint", desc: "Святая мученица Манефа, родом из Скифской страны, была схвачена вместе со святыми мучениками Антонином, Никифором и Германом в Кесарии Палестинской. Ее для поругания нагою водили по городу и затем предали различным мучениям, из которых она с помощью Божиею вышла невредимою." },
  { key: "11-27", name: "Ап. Филиппа", kind: "saint", desc: "Ап. Филипп, уроженец Вифсаиды, упоминается в Евангелии как тот, кто привел к Иисусу ап. Нафанаила, участвовал в чуде насыщения 5000 и задавал вопросы на Тайной Вечере.", lifeId: "filipp" },
  { key: "11-27", name: "Прп. Филиппа Ирапского", kind: "saint", desc: "Преподобный Филипп, в миру Феофил, был основателем Ирапской пустыни. Не помнивший родителей, круглый сирота, 12-летний Феофил поселился вблизи Комельской обители и жил подаянием." },
  { key: "11-27", name: "свт. Григория Паламы, архиепископа Фессалонитского", kind: "saint", desc: "Святитель Григорий Палама, архиепископ Солунский, родился в 1296 году в Малой Азии. Во время турецкого нашествия семья бежала в Константинополь и нашла приют при дворе Андроника II Палеолога (1282–1328)." },
  { key: "11-27", name: "Димитрия Беневоленского", kind: "saint", desc: "Священномученик Димитрий родился 10 октября 1883 года в городе Вышнем Волочке Тверской губернии в семье священника Михаила Беневоленского. Дмитрий Михайлович учился сначала в Тверской, а затем в Санкт-Петербургской Духовной семинарии, котор" },
  { key: "11-27", name: "Александра Быкова", kind: "saint", desc: "Священномученик Александр родился 8 августа 1881 года в селе Кельи Волоколамского уезда Московской губернии в семье торговца Иакова Быкова. Окончив земскую школу, Александр стал помогать отцу в торговле, а недостаток образования восполнил со временем самообразованием." },
  { key: "11-27", name: "Виктора Ильинского", kind: "saint", desc: "Священномученик Виктор родился 31 октября 1872 года в селе Кой Кашинского уезда Тверской губернии в семье диакона Николая Ильинского. Он окончил учительские курсы при уездном училище в Новгородской губернии и вернулся в родное село, где служил, будучи к этому времени рукоположен в сан священника, его отец." },
  { key: "11-27", name: "Алексия Нечаева", kind: "saint", desc: "Священномученик Алексий родился в 1875 году в селе Рамешки Бежецкого уезда Тверской губернии в семье священника Ефрема Нечаева [1] . По окончании Духовной семинарии он был рукоположен в сан священника." },
  { key: "11-27", name: "Михаила Белюстина", kind: "saint", desc: "Священномученик Михаил родился 1 марта 1881 года в городе Твери в семье чиновника Тверской консистории Николая Белюстина. Окончил Тверскую Духовную семинарию." },
  { key: "11-27", name: "Михаила Некрасова", kind: "saint", desc: "О иных наших мучениках остались в качестве свидетельства об их подвиге только драгоценные мученические акты: анкета, заполненная следователем при аресте, листы допроса, неправедный приговор и документ о расстреле." },
  { key: "11-27", name: "Феодора Баккалинского", kind: "saint", desc: "Священномученик Феодор родился 8 февраля 1880 года в селе Зарудье Радомысльского уезда Киевской губернии в семье церковнослужителя Павла Баккалинского." },
  { key: "11-27", name: "Петра Титова", kind: "saint", desc: "Иерей Петр был одним из тех, кто сознательно избрал путь служения Богу и Церкви во время беспощадных гонений. Для него было ясно при самом выборе священнического служения, что власть, с такой яростью исповедующая воинствующее безбожие, к Церкви и ее служителям будет беспощадна." },
  { key: "11-27", name: "Алексия Никологорского", kind: "saint", desc: "Священномученик Алексий родился в 1869 году в селе Нагорном Дмитровского уезда Московской губернии в семье псаломщика Семена Никологорского. В 1889 году Алексей Семенович окончил Духовную семинарию и был рукоположен в сан священника ко храму в селе Волочаново Волоколамского уезда Московской губернии." },
  { key: "11-27", name: "Сергия Знаменского", kind: "saint", desc: "Священномученик Сергий родился 10 апреля 1873 года в городе Чите в семье священника Иоанна Знаменского. Отец умер рано, и Сергей воспитывался в доме деда – сельского псаломщика." },
  { key: "11-27", name: "Николая Дунаева", kind: "saint", desc: "Священномученик Николай Дунаев родился 30 ноября 1878 года в д. Зименки Ковровского уезда Владимирской губернии. В 1920 году семья о. Николая, в которой было трое детей была раскулачена, в 1924 г." },
  { key: "11-28", name: "прп. Паисия Величковского", kind: "saint", desc: "Архимандрит Нямецкого монастыря в Молдавии. Родился он в 1722 г. в городе Полтаве в семье протоиерея, 17-ти лет вступил в Любечский монастырь, перешел в скит Трейстены в Молдавии, оттуда – в скит Керкул, отличавшийся особенной строгостью монашеской жизни." },
  { key: "11-28", name: "мч. Димитрия Дабудского", kind: "saint", desc: "Святой мученик Димитрий происходил из селения Дабуда, во Фракии, и пострадал при императоре Максимиане Галерии и его соправителе Максимине. Фракийскому префекту Публию донесли на святого, что он христианин, и по приказанию префекта святой был схвачен." },
  { key: "11-28", name: "Николая Щербакова", kind: "saint", desc: "Николай Павлович Щербаков родился 24 июля 1876 года в селе Лабазы Бузулукского уезда Самарской губернии в семье священника. После окончания Самарской духовной семинарии и женитьбы, он принял сан и был отправлен служить в город Чапаевск Самарской области." },
  { key: "11-28", name: "Петра Канардова", kind: "saint", desc: "Петр Иванович Канардов (Конардов) родился в селе Троицкое Московской губернии в 1870 году. Он происходил из священнической семьи. Пойдя по стопам отца, Петр заканчивает Духовную семинарию, после чего его посвящают в диаконы." },
  { key: "11-28", name: "Никиты Алмазова, протодиакона", kind: "saint", desc: "Протодиакон Никита Григорьевич Алмазов родился в 1874 году в селе Сущево Смоленской губернии в семье священника. Свое служение Церкви начал в должности псаломщика." },
  { key: "11-28", name: "мч. Григория Долинина", kind: "saint", desc: "Мученик [1] Григорий Иванович Долинин родился в 1875 году в селе Хохлово Нижегородской губернии. Происходил он из крестьянской семьи и образование получил в сельской школе." },
  { key: "11-28", name: "Купятицкая", year: "1182", kind: "saint", desc: "Явление самой древней на Белорусской земле Купятицкой иконы Божией Матери произошло в 1182 году около села Купятичи, расположенного на реке Ясельда в пределах бывшего Пинского уезда Минской губернии." },
  { key: "11-29", name: "Апостола и евангелиста Матфея", kind: "saint", desc: "Ап. Матфей, бывший мытарь, был призван Христом словами: \"Иди за Мной\". Оставив всё, он последовал за Спасителем и впоследствии написал Евангелие на еврейском языке.", lifeId: "matfey" },
  { key: "11-29", name: "Прав. Фулвиана, кн. Ефиопского, во Святом Крещении Матфея", kind: "saint", desc: "Святой апостол и евангелист Матфей, именуемый также Левием ( Мк.2,14 ; Лк.5,27 ), обошел с благовестием Сирию, Мидию, Персию, Парфию, закончив свои проповеднические труды мученической кончиной в Ефиопии." },
  { key: "11-29", name: "прмч. Филумена Святогробца (Хасаписа), архимандрита", kind: "saint", desc: "В 1927 году поступил в число насельников монастыря Ставровуни вместе со своим братом Александром. В 1934 году братья приехали в Иерусалим и поступили в гимназию Иерусалимской Православной Церкви." },
  { key: "11-29", name: "Сщмч. Феодора Колерова, пресвитера и с ним", kind: "saint", desc: "Феодор Ксенофонтович Колеров родился в 1882 году в селе Семеновском Тверской губернии в семье священника Ксенофонта Захарьевича и его жены Елизаветы Ивановны." },
  { key: "11-29", name: "Иоанна Цветкова", kind: "saint", desc: "При беспощадных гонениях на Русскую Православную Церковь в советской России все меньше оставалось священников, рукоположенных в дореволюционное время, и архиереи стали рукополагать в сан священника благочестивых мирян, дабы паства не осталась без духовного руководства и таинств, и не были закрыты храмы." },
  { key: "11-29", name: "Николая Троицкого", kind: "saint", desc: "Священномученик Николай родился 23 июля 1887 года в Тверской губернии в селе Покров, где служил в храме его отец, протоиерей Иоанн Троицкий. По окончании Духовной семинарии Николай Иванович был рукоположен в сан священника ко храму села Покров недалеко от города Удомля." },
  { key: "11-29", name: "Виктора Воронова", kind: "saint", desc: "Священномученик Виктор (Виктор Иванович Воронов) родился 10 марта 1889 года в городе Вышнем Волочке Тверской губернии [1] . В 1923 году он был рукоположен в сан священника к одному из городских храмов." },
  { key: "11-29", name: "Василия Соколова", kind: "saint", desc: "Василий Александрович Соколов родился 5 мая 1880 года в деревне Чёрный Ручей Вышневолоцкого уезда Тверской губернии в семье псаломщика. После рукоположения во иерея служил в храмах Тверской епархии." },
  { key: "11-29", name: "Макария Соловьева", kind: "saint", desc: "Макарий Арсеньевич Соловьев родился в деревне Скорнево Максатихинского района Тверской области в 1876 году. О периоде его жизни от рождения до первого ареста практически ничего не известно, мы знаем только, что он избрал духовный путь и был рукоположен в сан священника." },
  { key: "11-29", name: "Михаила Абрамова", kind: "saint", desc: "Михаил Иванович Абрамов родился 1 ноября 1885 г. (по другим документам 3 ноября 1885 г.) в деревне Роговая, Дурновской волости, Пронского уезда, Рязанской губернии в крестьянской семье." },
  { key: "11-29", name: "прмч. Пантелеимона (Аржаных), игумена", kind: "saint", desc: "Преподобномученик Пантелеймон родился 29 июня 1872 года в деревне Залипаевка Федоровской волости Мало-Архангельского уезда Орловской губернии в семье крестьянина Тимофея Аржаных и в крещении был наречен Павлом.", lifeId: "panteleimon" },
  { key: "11-29", name: "мч. Димитрия Спиридонова", kind: "saint", desc: "Димитрий Спиридонович Спиридонов родился в 1871 году. Еще в Таврической духовной семинарии он выделялся среди товарищей замечательными способностями, дававшими основание его родителям возложить на него большие надежды, и, в известном смысле, он их оправдал." },
  { key: "11-30", name: "Свт. Григория Чудотворца, епископа Неокесарийского", kind: "saint", desc: "Святитель Григорий родился в г. Неокесарии (север Малой Азии). В юности он учился в Александрии у знаменитого учителя, пресвитера Оригена . Вернувшись в Неокесарию, Григорий удалился в пустыню, где в посте и молитве стяжал высокое духовное совершенство и дары прозорливости и пророчества." },
  { key: "11-30", name: "прп. Никона, игумена Радонежского, ученика прп. Сергия", kind: "icon", desc: "Ученик преподобного Сергия Радонежского. Родился в Юрьеве-Польском. В юном возрасте, услышав об Ангельской жизни преподобного Сергия и желая последовать ему, святой пришел к преподобному Сергию и просил приобщения к лику монашествующих." },
  { key: "11-30", name: "прп. Лазаря иконописца, иеромонаха", kind: "icon", desc: "Святой преподобный Лазарь иконописец жил в Константинополе. Он был пресвитером, вел строгую подвижническую жизнь и писал святые иконы. При императоре-иконоборце Феофиле (829–842) его схватили и после тяжелых пыток бросили в темницу." },
  { key: "11-30", name: "мч. Гоброна, во Святом Крещении Михаила, и с ним 133-х воинов (914)", kind: "saint", desc: "Мученик Гоброн, во Святом Крещении Михаил, и с ним 133 воина – грузинские мученики Х века. Мученик Михаил, происходивший из знатного княжеского рода, с юных лет отличался храбростью и неустрашимостью, за что и был прозван Гоброном (что значит на арабском языке &quot;мужественный, храбрый&quot;)." },
  { key: "11-30", name: "прп. Севастиана Джексонского, архимандрита (1940)", kind: "saint", desc: "Преподобный Севастиан (Дабович) Джексонский родился 9 июня 1863 года в Сан-Франциско в семье сербских эмигрантов. Обучался в Киевской и Санкт-Петербургской духовных академиях." },
];
